startGuideActionMenu: "Επιλογή μενού",
startGuideActivity: "Οι δραστηριότητες είναι εργασίες προγραμματισμένες στα έργα σας. <br/>Μπορείτε να δημιουργήσετε την δομή των έργων σας. <br/>Δεν υπάρχει περιορισμός στο πλήθος επιπέδων των φάσεων / υποφάσεων / εργασιών / υποεργασιών ....",
startGuideAffectation: "Ένας πόρος πρέπει να αποδοθεί σε ένα έργο για να δει τα στοιχεία του. <br/> Η πρόσβαση παρέχετε και στα υποέργα",
startGuideClient: "Οι πελάτες είναι οι οντότητες για τις οποίες εργάζεστε<br/> Μπορούν να είναι εωτερικοί στο έργο ή εξωτερικοί.",
startGuideContact: "Οι επαφές είναι άτομα των πελατών με τις οποίες μπορείτε να έρθετε σε επαφή",
startGuideFooter: "Βασικές δυνατότητες",
startGuideImputation: "Οι πόροι εισάγουν την πραγματική εργασίας τους στην οθόνη Πραγματική Κατανομή Εργασίας μέρα με την μέρα εργασία με την εργασία",
startGuideIntro: "Βασική Βοήθεια. Πατήστε F1 για περισσότερα",
startGuideMilestone: "Τα Ορόσημα είναι ημερομηνίες κλειδιά για τα Έργα σας<br/> Μπορούν να είναι σταθερά η μετακινούμενα.",
startGuidePlanning: "Ο σχεδιασμός προτείνει ένα Gantt γράφημα.<br/>Για να προγραμματίσετε εργασίες πρέπει να αποδόσετε πόρους στις εργασίες και να ορίσετε εργασίες που πρέπει να γίνουν.<br/>Μετά μπορείτε να ορίσετε σχέσεις ανάμεσα σε εργασίες και ορόσημα.<br/>Μετά μπορείτε να εκτελέσετε τους υπολογισμούς κατανομής έργου.",
startGuideProject: "Το Έργο είναι το βασικό στοιχείο του ProjeQtOr.<br/>Κάθε στοιχείο είναι συνδεδεμένο με κάποιο Έργο.<br/> Τα δικαιώματα πρόσβασης έχουν άμεση σχέση εμ το Έργο.",
startGuideResource: "Οι πόροι είναι άτομα που θα δουλέψουν στις εργασίες.<br/>Αν επιλέξετε την επιλογή « είναι χρήστης » τότε οι ποροί θα μπορούν να συνδεθούν στο ProjeQtOr.",
startGuideTicket: "Τα Αιτήματα είναι συμβάντα που δεν έχετε προγραμματίσει. Μπορεί να είναι Bugs ή αιτήσεις γενικότερα<br/>Μπορούν να αντιγραφούν στις εργασίες χωρίς να χρειάζεται να ξαναεισάγετε πληροφορίες. Θα δημιουργηθεί και μια σύνδεση με το αρχικό αίτημα.",
startGuideTitle: "Αρχικός Οδηγός",
startGuideUser: "ΟΙ Χρήστες μπορούν να συνδεθούν στην εφαρμογή. <br/>Πρέπει να έχουν ένα προφιλ το οποίο θα καθορίζει τα δικαιώματα πρόσβασης που έχουν.",
